(() => {
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const days = () => [
    {period:'Antes de embarcar',title:'Sua viagem, bem preparada',text:'Confira os documentos exigidos para {{destino}}, os vouchers emitidos e os contatos de assistência. Registre aqui as orientações verificadas pela {{agencia}}.'},
    {period:'Chegada',title:'Boas-vindas ao destino',text:'Inclua o voo emitido, ponto de encontro do traslado e endereço da hospedagem conforme os vouchers. Identifique horários e serviços ainda pendentes de confirmação.'},
    {period:'Durante a viagem',title:'Experiências no seu ritmo',text:'Organize um dia por etapa. Diferencie os serviços contratados das sugestões de passeios e deixe espaço para tempo livre. Adapte as orientações ao perfil de {{cliente}}.'},
    {period:'Retorno',title:'Até a próxima descoberta',text:'Confira o traslado de saída, orientações de check-out e voo de retorno nos documentos emitidos. Acrescente os canais de suporte da agência.'}
  ];
  const models = [
    {id:'tp-editorial-v1',name:'Horizonte · Editorial',subtitle:'Fotografia ampla, respiro e narrativa por dia',kind:'TravelPro + Europlus',layout:'editorial',photo:'amalfi.jpg',days:days()},
    {id:'tp-concierge-v1',name:'Atlas · Concierge',subtitle:'Agenda clara, serviços e orientações à mão',kind:'TravelPro + Europlus',layout:'concierge',photo:'florence.jpg',days:days()}
  ];
  function catalog(saved=[]){return [...saved,...models.filter(m=>!saved.some(t=>t.id===m.id))];}
  function footer(base){return `<footer class="partners"><span>Uma viagem com a assinatura da sua agência</span><div><figure><small>Tecnologia</small><img src="${esc(base)}assets/travelpro-assinatura-final.png" alt="TravelPro"></figure><figure><small>Operadora</small><img src="${esc(base)}assets/europlus-logo.png" alt="Europlus"></figure></div></footer>`;}
  function render(r,model,{agency,brand={},base='',cover='',period='',preview=false}={}){
    const primary=/^#[a-f\d]{6}$/i.test(brand.primary||'')?brand.primary:'#244638';
    const theme=globalThis.TravelProposalBrand?.theme({...brand,primary})||{from:primary,to:'#182e27',tint:'#f1f4ef'};
    const logo=/^data:image\/png;base64,[a-z\d+/=]+$/i.test(brand.logo||'')?brand.logo:'';
    const style=model.layout==='concierge'?'concierge':'editorial';
    return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(r.name)}</title><style>
    *{box-sizing:border-box}body{margin:0;background:#e9ece8;font:15px/1.75 Arial,sans-serif;color:#233c32}main{max-width:860px;margin:auto;background:#fcfcf9}h1,h2,p,figure{margin:0}h1{font-size:48px;line-height:1.08;letter-spacing:-2px;max-width:650px}h2{font-size:28px;line-height:1.25;letter-spacing:-.7px}small,.eyebrow{font-size:10px;letter-spacing:2px;text-transform:uppercase}.agency{display:flex;align-items:center;gap:18px;padding:30px 48px;font-weight:600}.agency img{width:120px;height:48px;object-fit:contain}.hero{background:linear-gradient(125deg,${theme.from},${theme.to});color:#fff}.hero .photo{width:100%;height:340px;object-fit:cover;display:block}.hero-copy{padding:42px 48px 48px}.hero-copy h1{margin:18px 0}.hero-copy p{opacity:.9}.ribbon{padding:20px 48px;display:flex;gap:30px;background:${theme.tint};font-size:12px}.intro{padding:38px 48px;border-bottom:1px solid #dce2da}.intro p{margin-top:12px;color:#617267}.chapter{padding:42px 48px;break-before:page}.chapter-head{display:flex;gap:22px;align-items:center;margin-bottom:26px}.number{font-size:42px;color:${theme.from};font-weight:700;line-height:1}.chapter-head small{color:#68776d}.chapter-head h2{margin-top:6px}.details{white-space:pre-wrap;overflow-wrap:anywhere;border-radius:20px;padding:30px;background:#f0f3ee;border:1px solid #e2e7de;box-shadow:7px 7px 18px #dfe4da,-7px -7px 18px #fff}.chapter-note{margin-top:24px;font-size:11px;color:#66766b}.partners{padding:30px 48px;border-top:1px solid #dce2da;margin-top:36px;font-size:10px;color:#6c776e;break-inside:avoid}.partners>div{display:flex;gap:34px;align-items:center;margin-top:18px}.partners figure{display:flex;flex-direction:column;gap:8px}.partners img{width:138px;height:40px;object-fit:contain;mix-blend-mode:multiply}.partners small{font-size:8px}.concierge .hero{display:grid;grid-template-columns:1.1fr 1fr}.concierge .hero .photo{height:100%;min-height:380px;order:2}.concierge .hero-copy{padding:44px 32px}.concierge h1{font-size:40px}.concierge .chapter{break-before:auto;border-bottom:1px solid #dce2da}.concierge .details{border-left:4px solid ${theme.from};border-radius:0 18px 18px 0}.preview{padding:12px 24px;background:#fff3d9;color:#654d21;font-size:12px}.chapter-head{break-after:avoid}.details{orphans:3;widows:3}@page{size:A4;margin:14mm}@media print{body,main{background:white}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}.hero .photo{height:260px}.hero,.intro,.agency,.ribbon,.chapter-head{break-inside:avoid}.chapter{padding:22px 0}.partners{padding:22px 0}.details{box-shadow:none}.preview{display:none}.hero-copy{padding:32px}.concierge .hero .photo{min-height:330px}}@media(max-width:550px){.agency,.hero-copy,.intro,.chapter,.partners{padding:26px}.ribbon{padding:18px 26px;flex-wrap:wrap;gap:12px}h1{font-size:36px}.hero .photo{height:220px}.concierge .hero{display:block}.concierge .hero .photo{min-height:0;height:200px}.details{padding:22px}}
    </style></head><body><main class="${style}">${preview?'<p class="preview">Prévia do modelo · conteúdo ilustrativo para personalizar</p>':''}<header class="agency">${logo?`<img src="${esc(logo)}" alt="Logo da agência">`:''}<span>${esc(agency||'Sua agência')}</span></header><section class="hero"><img class="photo" src="${esc(cover||base+'assets/'+(model.photo||'amalfi.jpg'))}" alt="Paisagem ilustrativa"><div class="hero-copy"><span class="eyebrow">${style==='concierge'?'Seu guia de viagem':'Uma viagem para guardar'}</span><h1>${esc(r.name)}</h1><p>${esc(r.destination)}</p></div></section><div class="ribbon"><span>${esc(period||'Roteiro personalizado')}</span><span>${r.days.length} etapas · ${esc(model.name)}</span></div><section class="intro"><small>Feito para você</small><h2>Cada detalhe, no seu tempo.</h2><p>Seu roteiro reúne a programação e as orientações da agência. Para horários e serviços confirmados, consulte os vouchers e bilhetes emitidos.</p></section>${r.days.map((d,i)=>`<section class="chapter"><div class="chapter-head"><span class="number">${String(i+1).padStart(2,'0')}</span><div><small>${esc(d.period)}</small><h2>${esc(d.title)}</h2></div></div><div class="details">${esc(d.text)}</div><p class="chapter-note">${esc(agency||'Sua agência')} · ${esc(r.destination)}</p></section>`).join('')}${footer(base)}</main></body></html>`;
  }
  globalThis.TravelItineraryModels={models,catalog,render,footer};
})();
